const XLSX = require("xlsx");
const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  WidthType, AlignmentType, HeadingLevel, BorderStyle
} = require("docx");
const fs = require("fs");

// ── Read Excel data ──────────────────────────────────────────────
const wb = XLSX.readFile("testbed/data/product_inventory.xlsx");
const rows = XLSX.utils.sheet_to_json(wb.Sheets["Products"]);

const totalProducts = rows.length;
const categories = [...new Set(rows.map(r => r["Category"]))];
const prices = rows.map(r => r["Price"]);
const minPrice = Math.min(...prices);
const maxPrice = Math.max(...prices);
const avgPrice = (prices.reduce((a, b) => a + b, 0) / prices.length).toFixed(2);
const allInStock = rows.every(r => r["In Stock"] === "Yes");

// Category breakdown
const catCounts = {};
rows.forEach(r => { catCounts[r["Category"]] = (catCounts[r["Category"]] || 0) + 1; });

// ── Build Word document ──────────────────────────────────────────
const doc = new Document({
  sections: [{
    properties: {},
    children: [
      // Title
      new Paragraph({
        heading: HeadingLevel.TITLE,
        alignment: AlignmentType.CENTER,
        spacing: { after: 300 },
        children: [new TextRun({ text: "Product Inventory Summary", bold: true, size: 48 })]
      }),

      // Date
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { after: 400 },
        children: [new TextRun({ text: `Generated on: ${new Date().toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric" })}`, italics: true, size: 22, color: "666666" })]
      }),

      // Overview heading
      new Paragraph({ heading: HeadingLevel.HEADING_1, spacing: { before: 200, after: 200 }, children: [new TextRun({ text: "Overview", bold: true })] }),

      new Paragraph({ spacing: { after: 120 }, children: [
        new TextRun({ text: `This report summarises the product inventory data sourced from ` }),
        new TextRun({ text: "product_inventory.xlsx", bold: true }),
        new TextRun({ text: `. The inventory contains a total of ` }),
        new TextRun({ text: `${totalProducts} products`, bold: true }),
        new TextRun({ text: ` spread across ` }),
        new TextRun({ text: `${categories.length} categories`, bold: true }),
        new TextRun({ text: "." })
      ]}),

      // Stock status
      new Paragraph({ spacing: { after: 120 }, children: [
        new TextRun({ text: "Stock Status: ", bold: true }),
        new TextRun({ text: allInStock
          ? 'All listed items are marked "In Stock" as Yes. No out-of-stock items were found in the dataset.'
          : "Some items are out of stock." })
      ]}),

      // Price stats
      new Paragraph({ spacing: { after: 120 }, children: [
        new TextRun({ text: "Price Range: ", bold: true }),
        new TextRun({ text: `$${minPrice} – $${maxPrice}  |  Average Price: $${avgPrice}` })
      ]}),

      // Category breakdown heading
      new Paragraph({ heading: HeadingLevel.HEADING_1, spacing: { before: 300, after: 200 }, children: [new TextRun({ text: "Category Breakdown", bold: true })] }),

      // Table
      new Table({
        width: { size: 100, type: WidthType.PERCENTAGE },
        rows: [
          // Header row
          new TableRow({
            tableHeader: true,
            children: ["Category", "No. of Products"].map(h =>
              new TableCell({
                shading: { fill: "2E74B5" },
                children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: h, bold: true, color: "FFFFFF", size: 22 })] })]
              })
            )
          }),
          // Data rows
          ...Object.entries(catCounts)
            .sort((a, b) => b[1] - a[1])
            .map(([cat, count]) =>
              new TableRow({
                children: [
                  new TableCell({ children: [new Paragraph({ children: [new TextRun({ text: cat, size: 22 })] })] }),
                  new TableCell({ children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: String(count), size: 22 })] })] })
                ]
              })
            )
        ]
      }),

      // Closing note
      new Paragraph({ spacing: { before: 400 }, children: [
        new TextRun({ text: "Note: ", bold: true, italics: true }),
        new TextRun({ text: "This summary was auto-generated from the Excel inventory file. For full product details, refer to the original spreadsheet.", italics: true })
      ]})
    ]
  }]
});

// ── Write to disk ────────────────────────────────────────────────
Packer.toBuffer(doc).then(buf => {
  const outPath = "testbed/data/inventory_summary.docx";
  fs.writeFileSync(outPath, buf);
  console.log(`✅  Word document saved to ${outPath}`);
});
